import{_ as e,c as r,o,ag as n}from"./chunks/framework.CPHm90Yq.js";const c=JSON.parse('{"title":"API","description":"","frontmatter":{"sidebar":"auto","title":"API","meta":[{"name":"description","content":"API documentation for the packages of the Argdown project."}]},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}'),t={name:"api/index.md"};function d(i,a,g,s,l,p){return o(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><p>The Argdown repository is a &quot;monorepo&quot; containing a number of different npm packages in its <code>/packages</code> folder. All are published under the <code>@argdown</code> namespace and the MIT license. The two most important packages are @argdown/core and @argdown/node. Both packages have their own extensively commented API documentation. Here is a list of all packages with links to their documentations or README files.</p><p>All packages except @argdown/sandbox are written in Typescript and compiled to Javascript.</p><h2 id="argdown-core" tabindex="-1">@argdown/core <a class="header-anchor" href="#argdown-core" aria-label="Permalink to &quot;@argdown/core&quot;">​</a></h2><p><a href="https://argdown.org/argdown-core/" target="_blank" rel="noreferrer">API documentation</a></p><p>Contains the Argdown parser and lexer, the basic ArgdownApplication class that manages plugins and the plugins for all central tasks, including the ParserPlugin, ModelPlugin, MapPlugin, HtmlExportPlugin, JSONExportPlugin, DotExportPlugin. This package is used in all tools using the Argdown parser.</p><h2 id="argdown-node" tabindex="-1">@argdown/node <a class="header-anchor" href="#argdown-node" aria-label="Permalink to &quot;@argdown/node&quot;">​</a></h2><p><a href="https://argdown.org/argdown-node/" target="_blank" rel="noreferrer">API documentation</a></p><p>Contains the AsynArgdownApplication subclass supporting asynchronous plugin methods. Instantiates this class with all plugins and processes preconfigured and predefined so that you can use it directly without any additional setup. Provides plugins that are specific to Argdown applications that are running in Node.js and not in the browser, for example the LoadFilePlugin and the SaveAsPlugin.</p><h2 id="argdown-image-export" tabindex="-1">@argdown/image-export <a class="header-anchor" href="#argdown-image-export" aria-label="Permalink to &quot;@argdown/image-export&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-image-export/README.md" target="_blank" rel="noreferrer">README</a></p><p>Provides png, jpg and webp export plugin. If installed (<code>npm install -g @argdown/image-export</code>) will be automatically used by <code>@argdown/cli</code> and <code>@argdown/pandoc-filter</code>. This is not part of <code>@argdown/node</code> because of its file size and dependency on chrome/chromium, which might cause problems in some linux installations.</p><h2 id="argdown-map-views" tabindex="-1">@argdown/map-views <a class="header-anchor" href="#argdown-map-views" aria-label="Permalink to &quot;@argdown/map-views&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-map-views/README.md" target="_blank" rel="noreferrer">README</a></p><p>Contains the VizJs and Dagre map views used in the live previews of @argdown/sandbox and argdown-vscode.</p><h2 id="argdown-web-components" tabindex="-1">@argdown/web-components <a class="header-anchor" href="#argdown-web-components" aria-label="Permalink to &quot;@argdown/web-components&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-web-components/README.md" target="_blank" rel="noreferrer">README</a></p><p>Contains web-component used in the markdown-it, remark, marked, gatsby plugins and the pandoc filter. The VSCode extension uses the component in the Markdown preview. The Argdown documentation also uses the web-component for all Argdown snippets.</p><h2 id="argdown-sandbox" tabindex="-1">@argdown/sandbox <a class="header-anchor" href="#argdown-sandbox" aria-label="Permalink to &quot;@argdown/sandbox&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-sandbox/README.md" target="_blank" rel="noreferrer">README</a></p><p>The browser-based editor. This is a Vue-application depending on @argdown/core and @argdown/map-views.</p><h2 id="argdown-language-server" tabindex="-1">@argdown/language-server <a class="header-anchor" href="#argdown-language-server" aria-label="Permalink to &quot;@argdown/language-server&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-language-server/README.md" target="_blank" rel="noreferrer">README</a></p><p>An editor-agnostic language server for the Argdown language with code linter, code assistance and code completion providers. Implements the <a href="https://langserver.org/" target="_blank" rel="noreferrer">language server protocol</a> and depends on @argdown/core and @argdown/node.</p><h2 id="argdown-vscode" tabindex="-1">@argdown/vscode <a class="header-anchor" href="#argdown-vscode" aria-label="Permalink to &quot;@argdown/vscode&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-vscode/README.md" target="_blank" rel="noreferrer">README</a></p><p>The VS Code extension, depending on @argdown/core, @argdown/node, @argdown/language-server and @argdown/map-views</p><h2 id="argdown-cli" tabindex="-1">@argdown/cli <a class="header-anchor" href="#argdown-cli" aria-label="Permalink to &quot;@argdown/cli&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-cli/Readme.md" target="_blank" rel="noreferrer">README</a></p><p>The commandline tool, depending on @argdown/node and @argdown/core.</p><h2 id="argdown-pandoc-filter" tabindex="-1">@argdown/pandoc-filter <a class="header-anchor" href="#argdown-pandoc-filter" aria-label="Permalink to &quot;@argdown/pandoc-filter&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-pandoc-filter/README.md" target="_blank" rel="noreferrer">README</a></p><p>Pandoc filter that allows to generate Argdown-in-Markdown pdfs and html files.</p><h2 id="argdown-markdown-it-plugin" tabindex="-1">@argdown/markdown-it-plugin <a class="header-anchor" href="#argdown-markdown-it-plugin" aria-label="Permalink to &quot;@argdown/markdown-it-plugin&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-markdown-it-plugin/README.md" target="_blank" rel="noreferrer">README</a></p><p>Markdown-it plugin that converts Argdown codeblocks to the web-component</p><h2 id="argdown-marked-plugin" tabindex="-1">@argdown/marked-plugin <a class="header-anchor" href="#argdown-marked-plugin" aria-label="Permalink to &quot;@argdown/marked-plugin&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-marked-plugin/README.md" target="_blank" rel="noreferrer">README</a></p><p>Marked plugin that converts Argdown codeblocks to the web-component</p><h2 id="argdown-remark-plugin" tabindex="-1">@argdown/remark-plugin <a class="header-anchor" href="#argdown-remark-plugin" aria-label="Permalink to &quot;@argdown/remark-plugin&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-remark-plugin/README.md" target="_blank" rel="noreferrer">README</a></p><p>Remark plugin that converts Argdown codeblocks to the web-component</p><h2 id="argdown-highlightjs" tabindex="-1">@argdown/highlightjs <a class="header-anchor" href="#argdown-highlightjs" aria-label="Permalink to &quot;@argdown/highlightjs&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-highlightjs/README.md" target="_blank" rel="noreferrer">README</a></p><p>Highlightjs syntax highlighting support for Argodwn.</p><h2 id="argdown-prism" tabindex="-1">@argdown/prism <a class="header-anchor" href="#argdown-prism" aria-label="Permalink to &quot;@argdown/prism&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-prism/README.md" target="_blank" rel="noreferrer">README</a></p><p>Prism.js syntax highlighting support for Argdown.</p><h2 id="argdown-codemirror-mode" tabindex="-1">@argdown/codemirror-mode <a class="header-anchor" href="#argdown-codemirror-mode" aria-label="Permalink to &quot;@argdown/codemirror-mode&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/argdown-codemirror-mode/README.md" target="_blank" rel="noreferrer">README</a></p><p>Simple Codemirror mode for Argdown syntax highlighting support.</p><h2 id="argvu" tabindex="-1">ArgVu <a class="header-anchor" href="#argvu" aria-label="Permalink to &quot;ArgVu&quot;">​</a></h2><p><a href="https://github.com/argdown/argdown/blob/master/packages/ArgVu/README.md" target="_blank" rel="noreferrer">README</a></p><p>A font for Argdown with nice ligatures.</p>',54)])])}const w=e(t,[["render",d]]);export{c as __pageData,w as default};
